        token.transfer(makeAddr("recipient"), 1); // Small transfer
        vm.roll(block.number + 1); // Ensure timestamp update

        // Validate ETH transfer
        uint256 finalAttackerBalance = attacker.balance;
        assertEq(finalAttackerBalance, initialAttackerBalance + 0.5 ether, "ETH not sent to buyback wallet");
        assertEq(
            address(token).balance, 
            initialContractBalance + 1 ether - 0.5 ether, 
            "Contract balance incorrect"
        );
    }
}
